DO $test$
DECLARE original jsonb; adjusted jsonb; actual jsonb; again jsonb; e jsonb; wealth jsonb; w jsonb; detail jsonb; x jsonb; failed boolean;
BEGIN
 original:='{"historical":{"days":[{"date":"2020-01-01","value":8}]},"current_future":{"events":[{"amount":7}],"days":[{"date":"2030-01-01","bank":{"balance":100},"fix86_columns":{"saldo_final":100,"liq_d0_1_recurso":50,"rsus_vested":20,"saldo_apos_rsu":170,"fgts":500,"posicao_economica_total":900,"extra":"keep"}},{"date":"2030-02-01","fix86_columns":{"saldo_final":80,"liq_d0_1_recurso":50,"rsus_vested":40,"saldo_apos_rsu":170,"fgts":500,"posicao_economica_total":900}}]}}';
 adjusted:='{"fgts_projection_contract":{"enabled":true,"monthly_estimate_brl":100},"current_future":{"days":[{"date":"2030-01-01","fix86_columns":{"rsus_vested":1,"saldo_apos_rsu":151,"fgts":100,"fgts_documental":0,"fgts_aportes_projetados":100,"fgts_projection_basis":"estimate"}},{"date":"2030-02-01","fix86_columns":{"rsus_vested":21,"saldo_apos_rsu":151,"fgts":200,"fgts_documental":0,"fgts_aportes_projetados":200,"fgts_projection_basis":"estimate"}}]}}';
 e:='{"version":"fgts-position-evidence-v386","status":"position_after_withdrawal_unavailable","balance_brl":null,"balance_as_of":null}';
 actual:=lts_fgts_private_v419.merge_flow(original,adjusted,e);
 PERFORM public.v419_assert('cash unchanged',actual#>'{current_future,days,0,fix86_columns,saldo_final}'=original#>'{current_future,days,0,fix86_columns,saldo_final}');
 PERFORM public.v419_assert('brokerage deduction not copied',actual#>>'{current_future,days,0,fix86_columns,rsus_vested}'='20');
 PERFORM public.v419_assert('available balance unchanged',actual#>>'{current_future,days,0,fix86_columns,saldo_apos_rsu}'='170');
 PERFORM public.v419_assert('first scenario correct',actual#>>'{current_future,days,0,fix86_columns,saldo_apos_fgts}'='270');
 PERFORM public.v419_assert('future scenario correct',actual#>>'{current_future,days,1,fix86_columns,saldo_apos_fgts}'='370');
 PERFORM public.v419_assert('economic delta only FGTS',actual#>>'{current_future,days,0,fix86_columns,posicao_economica_total}'='500');
 PERFORM public.v419_assert('history unchanged',actual->'historical'=original->'historical');
 PERFORM public.v419_assert('events unchanged',actual#>'{current_future,events}'=original#>'{current_future,events}');
 PERFORM public.v419_assert('bank unchanged',actual#>'{current_future,days,0,bank}'=original#>'{current_future,days,0,bank}');
 PERFORM public.v419_assert('unknown documentary not zero',actual#>'{current_future,days,0,fix86_columns,fgts_documented_balance_brl}'='null'::jsonb);
 PERFORM public.v419_assert('unknown documentary marked',actual#>'{current_future,days,0,fix86_columns,fgts_documented_balance_available}'='false'::jsonb);
 again:=lts_fgts_private_v419.merge_flow(actual,adjusted,e);
 PERFORM public.v419_assert('merge idempotent',again=actual);
 failed:=false;BEGIN PERFORM lts_fgts_private_v419.merge_flow(original,jsonb_set(adjusted,'{current_future,days}','[]'),e);EXCEPTION WHEN OTHERS THEN failed:=true;END;
 PERFORM public.v419_assert('missing row refused',failed);
 failed:=false;BEGIN PERFORM lts_fgts_private_v419.merge_flow(original,jsonb_set(adjusted,'{current_future,days,0,date}','"2030-01-02"'),e);EXCEPTION WHEN OTHERS THEN failed:=true;END;
 PERFORM public.v419_assert('wrong date refused',failed);
 x:=lts_fgts_private_v419.merge_flow(original,jsonb_set(adjusted,'{current_future,days,0,fix86_columns,fgts}','null'),e);
 PERFORM public.v419_assert('unknown scenario not covered as zero',x#>'{current_future,days,0,fix86_columns,saldo_apos_fgts}'='null'::jsonb);
 wealth:='{"version":"unchanged","summary":{"assets_central":10000,"net_worth_central":7000,"net_worth_low":6000,"net_worth_high":8000,"known_debt_total":3000},"assets":{"cipo_396":{"market_central":5000}},"liquidity":{"bank_cash":100,"d0":50,"d3":20,"through_d3":170,"fgts_contingency":500},"distribution":[{"name":"FGTS","value":500},{"name":"Other","value":400}]}';
 w:=lts_fgts_private_v419.wealth(wealth,e,100);
 PERFORM public.v419_assert('wealth unknown stays null',w#>'{liquidity,fgts_contingency}'='null'::jsonb);
 PERFORM public.v419_assert('known assets exclude withdrawn balance',w#>>'{summary,assets_central}'='9500');
 PERFORM public.v419_assert('known net excludes withdrawn balance',w#>>'{summary,net_worth_central}'='6500');
 PERFORM public.v419_assert('cash wealth preserved',w#>>'{liquidity,through_d3}'='170');
 PERFORM public.v419_assert('estimate separate from actual',w#>>'{liquidity,fgts_scenario_estimate_brl}'='100');
 PERFORM public.v419_assert('unknown distribution null',w#>'{distribution,0,value}'='null'::jsonb);
 PERFORM public.v419_assert('other distribution unchanged',w#>'{distribution,1}'=wealth#>'{distribution,1}');
 PERFORM public.v419_assert('wealth reconciliation idempotent',lts_fgts_private_v419.wealth(w,e,100)=w);
 e:='{"status":"dated_documentary_position","balance_brl":300,"balance_as_of":"2030-01-01"}';
 x:=lts_fgts_private_v419.wealth(wealth,e,400);
 PERFORM public.v419_assert('later statement supersedes old balance',x#>>'{summary,assets_central}'='9800' AND x#>>'{liquidity,fgts_contingency}'='300');
 PERFORM public.v419_assert('later statement flagged confirmed',x#>>'{summary,fgts_balance_confirmed}'='true');
 PERFORM public.v419_assert('later known zero is legitimate',lts_fgts_private_v419.wealth(wealth,jsonb_set(e,'{balance_brl}','0'),100)#>>'{liquidity,fgts_contingency}'='0');
 detail:=jsonb_build_object('wealth',wealth,'wealth_v167',jsonb_build_object('assets_central_including_pensions',11000,'net_worth_central_including_pensions',8000));
 x:=lts_fgts_private_v419.wealth_detail(detail,e);
 PERFORM public.v419_assert('pensions preserved in gross',x#>>'{wealth_v167,assets_central_including_pensions}'='10800');
 PERFORM public.v419_assert('pensions preserved in net',x#>>'{wealth_v167,net_worth_central_including_pensions}'='7800');
 PERFORM public.v419_assert('detail idempotent',lts_fgts_private_v419.wealth_detail(x,e)=x);
 FOR x IN SELECT to_jsonb(r) FROM public.lts_dashboard_cash_ladder_from_flow_v1('00000000-0000-4000-8000-000000000001','2030-01-01','2030-02-01',jsonb_build_object('days',actual#>'{current_future,days}'))r LOOP
  PERFORM public.v419_assert('daily ladder '||(x->>'flow_date'),(x->>'fgts_projected')::numeric=CASE WHEN x->>'flow_date'='2030-01-01' THEN 100 ELSE 200 END);
  PERFORM public.v419_assert('ladder preserves cash layers '||(x->>'flow_date'),(x->>'balance_with_scheduled_vesting')::numeric=170);
 END LOOP;
 PERFORM public.v419_assert('missing ladder FGTS is null',(SELECT fgts_projected IS NULL AND balance_with_fgts IS NULL FROM public.lts_dashboard_cash_ladder_from_flow_v1('00000000-0000-4000-8000-000000000001','2030-01-01','2030-01-01',jsonb_set(jsonb_build_object('days',actual#>'{current_future,days}'),'{days,0,fix86_columns,fgts}','null'))));
 PERFORM public.v419_assert('private helpers not user callable',NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='lts_fgts_private_v419' AND (has_function_privilege('anon',p.oid,'EXECUTE') OR has_function_privilege('authenticated',p.oid,'EXECUTE'))));
END $test$;
SELECT jsonb_build_object('passed',bool_and(passed),'count',count(*),'checks',jsonb_agg(name ORDER BY name)) AS result FROM public.v419_tests;
